mapper.select:
select u.order_id, o.order_no, o.order_title, o.status as order_status, o.contract_id, o.connector_id, o.commodity_id, o.commodity_name, count(u.id) as usage_count, coalesce(sum(u.usage_value), 0) as total_usage_value, coalesce(sum(u.billable_usage), 0) as total_billable_usage, coalesce(sum(u.amount), 0) as total_amount, max(u.recorded_at) as latest_recorded_at from trading.usage_record u left join trading.trade_order o on o.id = u.order_id and o.deleted = 0 where 1 = 1
and u.order_id = #{query.orderId}
group by u.order_id, o.order_no, o.order_title, o.status, o.contract_id, o.connector_id, o.commodity_id, o.commodity_name order by latest_recorded_at desc
limit #{query.limit}
